Why not have this exposed to the user, but any use of it, say

vector[N] values;
matrix[N, N] vectors;
matrix[N, N] X;

(values, vectors) = eigendecomposition(X);

get parsed as

void eigendecompose(const matrix& x, vector& values, matrix& vectors,) {

    vector eigenval;
    matrix eigenvecs;
    eigenvals <- eigenvalues(x);
    eigenvecs <- eigenvectors(x);
}

